export function SecurityWarning({
  heading = "{{heading}}",
  detail = "{{detail}}",
  severity = "{{severity}}",
  showAction = {{showAction}},
}) {
  const theme = {
    Info: { bg: "#EAF3FB", border: "#BFD9F2", iconBg: "#BFD9F2", iconColor: "#14263a" },
    Warning: { bg: "#FDF3E2", border: "#E8A020", iconBg: "#E8A020", iconColor: "#241430" },
    Critical: { bg: "#FBEAEA", border: "#D64545", iconBg: "#D64545", iconColor: "#FAF7F2" },
  }[severity] ?? {};
  return (
    <div role="alert" style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", width: 360, padding: "14px 16px", borderRadius: 10, boxSizing: "border-box", display: "flex", gap: 12, border: `1.5px solid ${theme.border}`, background: theme.bg }}>
      <span aria-hidden="true" style={{ flex: "none", width: 22, height: 22, borderRadius: 999, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 13, background: theme.iconBg, color: theme.iconColor }}>!</span>
      <div>
        <p style={{ margin: 0, fontWeight: 700 }}>{heading}</p>
        <p style={{ margin: "4px 0 0", fontSize: 12, opacity: .8 }}>{detail}</p>
        {showAction && <button type="button" style={{ marginTop: 10, padding: "6px 12px", borderRadius: 7, border: "1.5px solid currentColor", background: "none", fontWeight: 700, fontSize: 12, cursor: "pointer", color: "inherit" }}>This wasn’t me</button>}
      </div>
    </div>
  );
}
